func MountSavedAnalyticViewHandler(mux loomhttp.Muxer, h http.Handler, corsPolicy loomhttp.RuntimeCORSPolicy) {
	h = corsPolicy.Handler(loomhttp.AsHandlerFunc(h))
	loomhttp.MountHandler(mux, "GET", "/api/workspaces/{slug}/saved-analytic-view/{analytic_id}/", h)
}

// NewSavedAnalyticViewHandler creates a HTTP handler which loads the HTTP
// request and calls the "workspace_analytics" service "saved_analytic_view"
// endpoint.
func NewSavedAnalyticViewHandler(
	endpoint loom.Endpoint,
	mux loomhttp.Muxer,
	decoder func(*http.Request) loomhttp.Decoder,
	encoder func(context.Context, http.ResponseWriter) loomhttp.Encoder,
	errhandler func(context.Context, http.ResponseWriter, error),
	formatter func(ctx context.Context, err error) loomhttp.StatusCoder,
) http.Handler {
	var (
		decodeRequest  = DecodeSavedAnalyticViewRequest(mux, decoder)
		encodeResponse = EncodeSavedAnalyticViewResponse(encoder)
		encodeError    = EncodeSavedAnalyticViewError(encoder, formatter)
	)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		lifecycle := loomhttp.NewHandlerLifecycle(w, r, "workspace_analytics", "saved_analytic_view")
		defer lifecycle.End()
		ctx := lifecycle.Context()
		w = lifecycle.Writer()
		payload, err := decodeRequest(r)
		if err != nil {
			lifecycle.DecodeFailed(err, encodeError, errhandler)
			return
		}
		res, err := endpoint(ctx, payload)
		if err != nil {
			lifecycle.HandlerFailed(err, false, encodeError, errhandler)
			return
		}
		o := res.(*workspaceanalytics.SavedAnalyticViewResponseData)
		lifecycle.WriteRawBody(o.Body, func(ctx context.Context, w http.ResponseWriter) error {
			return encodeResponse(ctx, w, o.Result)
		}, encodeError, errhandler)
		return
	})
}
